const input = $input.first().json;
const segments = input.segments ?? [];
return segments.map((segment, index) => ({
  json: {
    title: input.title,
    hashtags: input.hashtags,
    provider: input.provider,
    language: input.language ?? "en",
    segmentIndex: index,
    text: segment.text,
    visualKeyword: segment.visualKeyword,
  },
}));

return $input.all().map((item) => {
  const data = item.json;
  const visuals = data.visuals ?? [];
  const visual = visuals[0] ?? null;
  return {
    json: {
      title: data.title,
      hashtags: data.hashtags,
      provider: data.provider,
      language: data.language,
      segmentIndex: data.segmentIndex,
      text: data.text,
      visualKeyword: data.visualKeyword,
      visual,
      visualNote: visual
        ? null
        : (data.note ?? "No free-licence video found for this keyword — upload your own footage for this segment."),
    },
  };
});

const segments = $input.all().map((item) => item.json);
const pad = (n) => String(n).padStart(2, "0");
const srtTime = (seconds) => {
  const totalMs = Math.max(0, Math.round(seconds * 1000));
  const ms = totalMs % 1000;
  const totalSec = Math.floor(totalMs / 1000);
  return `${pad(Math.floor(totalSec / 3600))}:${pad(Math.floor(totalSec / 60) % 60)}:${pad(totalSec % 60)},${String(ms).padStart(3, "0")}`;
};
const vttTime = (seconds) => srtTime(seconds).replace(",", ".");
let srt = "";
let vtt = "WEBVTT\n\n";
segments.forEach((segment, index) => {
  const start = index * 5;
  const end = (index + 1) * 5;
  srt += `${index + 1}\n${srtTime(start)} --> ${srtTime(end)}\n${segment.text}\n\n`;
  vtt += `${vttTime(start)} --> ${vttTime(end)}\n${segment.text}\n\n`;
});
const first = segments[0] ?? {};
const voiceoverText = segments.map((s) => s.text).join(" ");
return [{
  json: {
    title: first.title,
    hashtags: first.hashtags,
    provider: first.provider,
    language: first.language ?? "en",
    segments,
    srt: srt.trim(),
    vtt: vtt.trim(),
    voiceoverText,
    voiceoverTooLong: voiceoverText.length > 500,
  },
}];

const subtitles = $('Build Subtitles').first().json;
const binary = $input.first().binary ?? {};
const hasAudio = Object.keys(binary).length > 0;
const voiceover = hasAudio
  ? { status: "generated", provider: "elevenlabs", textLength: subtitles.voiceoverText.length, note: "Audio bytes from this run are in the workflow binary data — add a storage step to keep them; this record holds the text, not the bytes." }
  : { status: "skipped", reason: "voiceover skipped — the voiceover route did not return audio (provider not configured or provider error); render continues without voiceover." };
return [{ json: { ...subtitles, voiceover } }];

const subtitles = $('Build Subtitles').first().json;
const wanted = $('Normalize Input').first().json.voiceover === true;
const voiceover = wanted
  ? { status: "skipped", reason: "voiceover skipped — script exceeds the 500-character voiceover limit" }
  : { status: "not_requested" };
return [{ json: { ...subtitles, voiceover } }];

const data = $input.first().json;
const format = $('Normalize Input').first().json.format ?? "9:16";
const dimensions = { "9:16": [720, 1280], "16:9": [1280, 720], "1:1": [720, 720] }[format] ?? [720, 1280];
const segments = data.segments ?? [];
const withVisual = segments.filter((s) => s.visual);
const attributionLines = [
  ...withVisual.map((s) => s.visual.attribution),
  `Script: AI-generated script (provider: ${data.provider}) — this record does not grant rights in anyone else's material.`,
];
const jobId = `n8n-${Date.now()}`;
return [{
  json: {
    jobId,
    status: "needs_render",
    title: data.title,
    hashtags: data.hashtags,
    language: data.language,
    format,
    width: dimensions[0],
    height: dimensions[1],
    subtitleStyle: { font: "system-ui, sans-serif", position: "bottom", color: "#ffffff", size: 46, stroke: false, background: "dark" },
    scriptProvider: data.provider,
    segments,
    segmentsWithoutVisuals: segments.length - withVisual.length,
    srt: data.srt,
    vtt: data.vtt,
    attribution: attributionLines.join("\n"),
    voiceover: data.voiceover,
    renderNote: "No video has been produced. Server-side rendering is not available on Vercel, so this job is a record only: render it in the browser renderer or forward it to the ffmpeg worker once that host exists. AI editing does not remove copyright — these visuals are CC-licensed or user-uploaded only.",
    provenance: {
      scriptProvider: data.provider,
      visualLicenses: withVisual.map((s) => s.visual.license),
      sourceUrls: withVisual.map((s) => s.visual.sourceUrl),
    },
  },
}];

const job = $input.first().json;
return [{
  json: {
    ...job,
    post: {
      clipId: `ai-combo-${job.jobId}`,
      title: job.title,
      hashtags: job.hashtags,
      note: "Nothing has been posted. When the rendered short is shared, record the outcome via POST /api/post-activity with this clip id — the outcome is never 'published', because only the platform itself can confirm a live post.",
    },
  },
}];
